import React, { useState, useEffect } from 'react';

function Leaderboard({ setCurrentPage }) {
  // Mock leaderboard data (in a real app, this would come from your server)
  const [leaderboardData, setLeaderboardData] = useState([
    { teamName: "Code Crackers", completionTime: 482, members: "Alex, Jamie, Taylor" },
    { teamName: "Puzzle Masters", completionTime: 527, members: "Jordan, Casey, Riley" },
    { teamName: "Riddle Solvers", completionTime: 595, members: "Morgan, Quinn, Sam" },
    { teamName: "Mystery Hunters", completionTime: 631, members: "Drew, Avery, Pat" },
    { teamName: "Clue Finders", completionTime: 712, members: "Charlie, Finley, Dakota" }
  ]);

  // Function to format time in minutes and seconds
  const formatTime = (seconds) => {
    const minutes = Math.floor(seconds / 60);
    const remainingSeconds = seconds % 60;
    return `${minutes}m ${remainingSeconds}s`;
  };

  // Function to go back to registration page
  const startNewGame = () => {
    setCurrentPage('register');
  };

  return (
    <div className="leaderboard-container">
      <h1>Leaderboard</h1>

      <table className="leaderboard-table">
        <thead>
          <tr>
            <th>Rank</th>
            <th>Team</th>
            <th>Time</th>
            <th>Members</th>
          </tr>
        </thead>
        <tbody>
          {leaderboardData.map((team, index) => (
            <tr key={index}>
              <td>{index + 1}</td>
              <td>{team.teamName}</td>
              <td>{formatTime(team.completionTime)}</td>
              <td>{team.members}</td>
            </tr>
          ))}
        </tbody>
      </table>

      <button onClick={startNewGame} className="new-game-button">
        Start New Game
      </button>
    </div>
  );
}

export default Leaderboard;
